import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict with side, price, qty, arrival, active
    buy_heap = []   # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    counter = 0

    def clean_buy():
        while buy_heap:
            negp, arr, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            p, arr, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    def match_incoming(side, price, qty, allow_book=False, incoming_id=None, arrival=None):
        # returns remaining qty
        remaining = qty
        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                p, arr, oid = sell_heap[0]
                if price is not None and p > price:
                    break
                o = book[oid]
                trade_qty = min(remaining, o['qty'])
                trades.append([incoming_id, oid, p, trade_qty])
                remaining -= trade_qty
                o['qty'] -= trade_qty
                if o['qty'] == 0:
                    heapq.heappop(sell_heap)
                    o['active'] = False
        else:
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negp, arr, oid = buy_heap[0]
                p = -negp
                if price is not None and p < price:
                    break
                o = book[oid]
                trade_qty = min(remaining, o['qty'])
                trades.append([oid, incoming_id, p, trade_qty])
                remaining -= trade_qty
                o['qty'] -= trade_qty
                if o['qty'] == 0:
                    heapq.heappop(buy_heap)
                    o['active'] = False
        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, incoming_id=oid)
            counter += 1
            arrival = counter
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'arrival': arrival, 'active': remaining > 0}
            if remaining > 0:
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, arrival, oid))
                else:
                    heapq.heappush(sell_heap, (price, arrival, oid))
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            match_incoming(side, price, qty, incoming_id=oid)
            # discard remainder, do not add to book
        elif typ == 'market':
            _, oid, side, qty = order
            match_incoming(side, None, qty, incoming_id=oid)
        elif typ == 'cancel':
            _, oid = order
            o = book.get(oid)
            if o is not None and o['active'] and o['qty'] > 0:
                o['active'] = False

    return trades

